const sameMemberIdentity = (left, right) => {
  const a = buildMember(left);
  const b = buildMember(right);
  return Boolean(
    (a.id && b.id && a.id === b.id)
    || (a.phone && b.phone && a.phone === b.phone)
    || (!a.id && !b.id && !a.phone && !b.phone && a.name.toLowerCase() === b.name.toLowerCase())
